async function fetchEquipmentStats() {
    try {
        const data = await api('/api/najika/equipment', 'POST');
        if (data && data.stats) {
            const atkEl = document.getElementById('equipAtk');
            const defEl = document.getElementById('equipDef');
            const hpEl = document.getElementById('equipHP');
            const mpEl = document.getElementById('equipMP');
            if (atkEl) atkEl.textContent = data.stats.atk || 0;
            if (defEl) defEl.textContent = data.stats.def || 0;
            if (hpEl) hpEl.textContent = data.stats.hp || 0;
            if (mpEl) mpEl.textContent = data.stats.mp || 0;
        }
    } catch (error) {
        console.warn('Equipment-Stats konnten nicht geladen werden.', error);
    }
}

async function praiseNajika() {
    try {
        const r = await api('/api/najika/praise', 'POST');
        alert(r.msg || 'Najika freut sich!');
        await fetchNajikaStatus();
    } catch (error) {
        alert('Loben nicht verfügbar.');
    }
}

async function scoldNajika() {
    try {
        const r = await api('/api/najika/scold', 'POST');
        alert(r.msg || 'Najika wurde getadelt!');
        await fetchNajikaStatus();
    } catch (error) {
        alert('Tadeln nicht verfügbar.');
    }
}

function toggleEquipmentPanel() {
    const content = document.getElementById('equipmentContent');
    const toggle = document.getElementById('equipmentToggle');
    if (content.style.display === 'none') {
        content.style.display = 'block';
        toggle.textContent = '▼';
    } else {
        content.style.display = 'none';
        toggle.textContent = '▶';
    }
}

