                alert(`Sieg! +${r.xp_earned} XP, +${r.gold_earned} Gold!`);
            } else if (r.result === 'defeat') {
                alert('Kampf verloren!');
            }
        }
    } catch (error) {
        alert('Kampf nicht verfügbar.');
        console.error(error);
    }
}

